// Single source of truth for every CMS content type.
// The dashboard editor, the API validation, the D1 repository and `schema.sql`
// (generated by `npm run db:generate`) are all driven by this file.
import type { CollectionKey } from "./types.ts";

export type FieldType =
  | "text"
  | "textarea"
  | "markdown"
  | "number"
  | "select"
  | "tags" // string[] edited as comma-separated values
  | "lines" // string[] edited one per line
  | "image" // URL, with R2 upload
  | "audio" // URL, with R2 upload
  | "media" // URL (video/audio/image), with R2 upload
  | "flame" // 5 Flame Burn Notice Score slider
  | "boolean"
  | "datetime";

export interface Field {
  name: string;
  label: string;
  type: FieldType;
  options?: { value: string; label: string }[];
  required?: boolean;
  help?: string;
  /** Only show this field when another field has one of these values */
  showWhen?: { field: string; in: string[] };
  /** Show as a column in the dashboard table */
  column?: boolean;
}

export interface Collection {
  key: CollectionKey;
  table: string;
  label: string;
  singular: string;
  description: string;
  titleField: string;
  orderBy: { field: string; dir: "asc" | "desc" };
  /** Public path where this content appears */
  publicPath: string;
  fields: Field[];
}

