export const collectionKeys = Object.keys(collections) as CollectionKey[];

export function isCollectionKey(value: string): value is CollectionKey {
  return Object.prototype.hasOwnProperty.call(collections, value);
}

export function isJsonField(field: Field): boolean {
  return field.type === "tags" || field.type === "lines";
}

export function sqlType(field: Field): "TEXT" | "REAL" | "INTEGER" {
  if (field.type === "number" || field.type === "flame") return "REAL";
  if (field.type === "boolean") return "INTEGER";
  return "TEXT";
}
